import * as React from "react";
import clsx from "clsx";
import "./TimelineInfoContent.scss";

export interface TimelineInfoContentProps {
  content: React.ReactNode;
  showLine?: boolean;
}

const TimelineInfoContent = ({
  content,
  showLine,
}: TimelineInfoContentProps) => {
  return (
    <div className="timeline-info-content-container">
      <div
        className={clsx("timeline-info-content-line", {
          "hide-content-line": !showLine,
        })}
      />
      <div className="timeline-info-content">{content}</div>
    </div>
  );
};

export default TimelineInfoContent;
